"""
LibreVDI settings overlay for the openUDS broker.

Loads the upstream ``settings.py.sample`` unchanged (so new upstream defaults such as
middleware or installed apps are picked up automatically) and then overrides only what
is needed to run in a container:

* configuration from environment variables (``LIBREVDI_*``), secrets also from ``*_FILE``
* PostgreSQL as database (the image does not ship the GPL-licensed MySQL driver)
* keys from files on the data volume (generated by ``librevdi-entrypoint init``)
* logging to stdout (text or JSON), no log files
* static files served by WhiteNoise, health/metrics endpoints via LibreVDI middleware
"""

# pylint: disable=wrong-import-position,invalid-name
import os
import runpy
import sys

from librevdi_ext import env

_here = os.path.dirname(os.path.abspath(__file__))
globals().update(
    {k: v for k, v in runpy.run_path(os.path.join(_here, "settings.py.sample")).items() if not k.startswith("__")}
)

_BUILDING = env.get_bool("LIBREVDI_BUILD", False)  # image build (collectstatic), no DB / keys
_TESTING = (
    any(arg.endswith("test") or "pytest/" in arg or "/pytest" in arg for arg in sys.argv)
    or "PYTEST_XDIST_WORKER" in os.environ
    or "TEST_UUID" in os.environ
)

DATA_DIR = env.get("UDS_DATA_DIR", "/var/lib/uds")

# --- General ---------------------------------------------------------------------------
DEBUG = env.get_bool("LIBREVDI_DEBUG", False)
DEBUG_LOG = DEBUG
TEMPLATES[0]["OPTIONS"]["debug"] = DEBUG  # type: ignore[name-defined]  # noqa: F821

ALLOWED_HOSTS = env.get_list("LIBREVDI_ALLOWED_HOSTS", ["*"])
TIME_ZONE = env.get("LIBREVDI_TIME_ZONE", "UTC")
LANGUAGE_CODE = env.get("LIBREVDI_LANGUAGE", "en")

_public_url = env.get("LIBREVDI_PUBLIC_URL", "")
CSRF_TRUSTED_ORIGINS = [_public_url.rstrip("/")] if _public_url else []
# Behind the bundled reverse proxy the original host/scheme come from X-Forwarded-*
USE_X_FORWARDED_HOST = env.get_bool("LIBREVDI_BEHIND_PROXY", True)

# Cookies only over HTTPS (the bundled proxy terminates TLS). HttpOnly stays as upstream:
# the Angular UI reads the CSRF cookie from JavaScript.
SESSION_COOKIE_SECURE = env.get_bool("LIBREVDI_SECURE_COOKIES", True)
CSRF_COOKIE_SECURE = SESSION_COOKIE_SECURE

# --- Secrets ---------------------------------------------------------------------------
if _BUILDING or _TESTING:
    from librevdi_ext import keys as _keys

    SECRET_KEY = _keys.random_secret()
    RSA_KEY = _keys.ephemeral_rsa_pem()
else:
    SECRET_KEY = env.get_secret(
        "LIBREVDI_SECRET_KEY", default_file=os.path.join(DATA_DIR, "keys", "secret_key"), required=True
    )
    RSA_KEY = env.get_secret("LIBREVDI_RSA_KEY", default_file=os.path.join(DATA_DIR, "keys", "rsa.pem"), required=True)

# Certificate used to sign .rdp files (transport option "Sign RDP file"); PEM cert+key or PFX
RDP_SIGN_CERT = env.get("LIBREVDI_RDP_SIGN_CERT") or os.path.join(DATA_DIR, "rdp-signing", "cert.pem")
RDP_SIGN_KEY = env.get("LIBREVDI_RDP_SIGN_KEY") or os.path.join(DATA_DIR, "rdp-signing", "key.pem")

# --- Databases -------------------------------------------------------------------------
if not _TESTING:
    if _BUILDING:
        DATABASES["default"] = {  # type: ignore[name-defined]  # noqa: F821
            "ENGINE": "django.db.backends.sqlite3",
            "NAME": ":memory:",
        }
    else:
        _engine = env.get("LIBREVDI_DB_ENGINE", "postgresql")
        _default_db: dict = {
            "ENGINE": f"django.db.backends.{_engine}",
            "NAME": env.get("LIBREVDI_DB_NAME", "librevdi"),
            "USER": env.get("LIBREVDI_DB_USER", "librevdi"),
            "PASSWORD": env.get_secret("LIBREVDI_DB_PASSWORD", required=True),
            "HOST": env.get("LIBREVDI_DB_HOST", "postgres"),
            "PORT": env.get("LIBREVDI_DB_PORT", "5432" if _engine == "postgresql" else "3306"),
            # 0 = close the connection after each request (upstream default). Persistent
            # connections must stay off under ASGI: every worker thread would keep its own
            # connection open and PostgreSQL runs out of slots ("too many clients").
            "CONN_MAX_AGE": env.get_int("LIBREVDI_DB_CONN_MAX_AGE", 0),
        }
        if _engine == "mysql":
            _default_db["OPTIONS"] = {"isolation_level": "read committed"}
        DATABASES["default"] = _default_db  # type: ignore[name-defined]  # noqa: F821

# Local per-node DB used by upstream for notifications; keep it on the data volume
DATABASES["persistent"]["NAME"] = (  # type: ignore[name-defined]  # noqa: F821
    ":memory:" if (_BUILDING or _TESTING) else os.path.join(DATA_DIR, "persistent.sqlite3")
)

# --- Caches ----------------------------------------------------------------------------
_memcached = env.get("LIBREVDI_MEMCACHED", "")
if _TESTING or _BUILDING or not _memcached:
    CACHES["memory"] = {"BACKEND": "django.core.cache.backends.locmem.LocMemCache"}  # type: ignore[name-defined]  # noqa: F821
else:
    CACHES["memory"] = {  # type: ignore[name-defined]  # noqa: F821
        "BACKEND": "django.core.cache.backends.memcached.PyLibMCCache",
        "LOCATION": _memcached,
    }

# --- Middleware / static files ---------------------------------------------------------
MIDDLEWARE = [
    "librevdi_ext.middleware.HealthMetricsMiddleware",  # /healthz, /readyz (before redirects)
    "whitenoise.middleware.WhiteNoiseMiddleware",
] + [m for m in MIDDLEWARE if "whitenoise" not in m]  # type: ignore[name-defined]  # noqa: F821
WHITENOISE_USE_FINDERS = False

# --- Logging ---------------------------------------------------------------------------
LOGDIR = "/app/log"  # upstream code may reference it; nothing is written there by default
LOGLEVEL = env.get("LIBREVDI_LOG_LEVEL", "DEBUG" if DEBUG else "INFO").upper()

from librevdi_ext.logging import build_logging_config  # noqa: E402

LOGGING = build_logging_config(
    LOGGING,  # type: ignore[name-defined]  # noqa: F821
    level=LOGLEVEL,
    fmt=env.get("LIBREVDI_LOG_FORMAT", "text"),
)
